const yyyy = date.getUTCFullYear();
const month = String(date.getUTCMonth() + 1).padStart(2, '0'); // month is 0-indexed
const day = String(date.getUTCDate()).padStart(2, '0');
const hour = String(date.getUTCHours()).padStart(2, '0');
const minute = String(date.getUTCMinutes()).padStart(2, '0');
//const hour='09';

//const minute='52';



node.warn(`Using UTC time: ${hour}:${minute} on ${yyyy}-${month}-${day}`);
//http://localhost:18001/swarmkb/log?date=2025-06-02&hour=18



const nodePorts = [18001, 18002, 18003, 18004, 18005, 18006, 18007, 18008];

const baseUrl = "http://localhost:";

const requests = nodePorts.map(port => ({
    url: `${baseUrl}${port}/swarmkb/log?date=${yyyy}-${month}-${day}&hour=${hour}&minute=${minute}`,
    node: `node-${port}`
}));

return [{ payload: requests }];

if (Array.isArray(msg.payload)) {
    let nodeId = "unknown";

    // Extract port from URL like "http://localhost:18003/..."
    const url = msg.url || "";
    const match = url.match(/localhost:(\d+)/);
    if (match && match[1]) {
        nodeId = `node-${match[1]}`;
    }

    msg.payload = msg.payload.map(log => {
        log.node = nodeId;
        return log;
    });
}
return msg;

msg.url = msg.payload.url;
msg.headers = msg.headers || {};
msg.headers._node = msg.payload.node;
msg.payload = {};
return msg;

const logs = Array.isArray(msg.payload) ? msg.payload : [];
const previous = context.get("logBuffer") || [];
const agentMap = {}; // map of node => logs array

logs.forEach(log => {
    const timestamp = log.timestamp || "N/A";
    const level = (log.level || "INFO").padEnd(10, " ");
    const node = (log.node || "unknown").padEnd(12, " ");
    const rawNode = log.node || "unknown";
    const message = log.message || "";

    // Format line with indentation for multiline messages
    const formattedMessage = message
        .split("\n")
        .map((line, idx) => idx === 0 ? line : "    " + line)
        .join("\n");

    const line = `[${timestamp}] [${level}] [${node}] ${formattedMessage}`;
    previous.push(line);

    // Store per-agent log line
    if (!agentMap[rawNode]) agentMap[rawNode] = [];
    agentMap[rawNode].push(line);
});

// Limit live buffer to last 100 lines
if (previous.length > 100) previous.splice(0, previous.length - 100);
context.set("logBuffer", previous);

// Convert map to array for UI
const agentLogs = Object.entries(agentMap).map(([node, logLines]) => ({
    node,
    logs: logLines.join("\n\n")
}));

msg.payload = {
    live: previous.join("\n\n"),
    agentLogs
};

return msg;

const logs = Array.isArray(msg.payload) ? msg.payload : [];

const buffer = context.get("logBuffer") || [];
const tableData = context.get("tableBuffer") || [];
let lineNumber = context.get("logLineNumber") || 1;

logs.forEach(log => {
    const line = `[${lineNumber}] [${log.timestamp}] [${log.level || 'INFO'}] [${log.node || 'unknown'}] ${log.message}`;
    buffer.push(line);

    tableData.push({
        line: lineNumber,
        timestamp: log.timestamp,
        level: log.level || 'INFO',
        message: log.message || '',
        source: log.source || '',
        node: log.node || 'unknown'
    });

    lineNumber++;
});

// Trim history to last 100
if (buffer.length > 100) buffer.splice(0, buffer.length - 100);
if (tableData.length > 100) tableData.splice(0, tableData.length - 100);

// Save context
context.set("logBuffer", buffer);
context.set("tableBuffer", tableData);
context.set("logLineNumber", lineNumber);

// Final output
msg.payload = {
    live: buffer.join("\n"),
    agentLogs_flat: tableData
};

return msg;

