const tableData = context.get("tableBuffer") || [];
const randomMetric = (min, max, decimals = 0) => {
    const value = Math.random() * (max - min) + min;
    return +value.toFixed(decimals);
};

logs.forEach(log => {

    tableData.push({
        timestamp: log.timestamp,
        //level: log.level || 'INFO',
        //message: log.message || '',
        source: log.source || '',
        node: log.node || 'unknown',
        cpu: +(Math.random() * 100).toFixed(2),
        mem: +(Math.random() * 100).toFixed(2),
        latency: +(Math.random() * 250).toFixed(2),
        health: +(Math.random() * 100).toFixed(2),
        replication: Math.floor(Math.random() * 1000),
        io: +(Math.random() * 100).toFixed(2),
        queryRate: +(Math.random() * 50).toFixed(2),
        role: Math.random() > 0.5 ? 'Coordinator' : 'Follower',
        ///////
        uptimeAgent: randomMetric(80, 100),               // Uptime (10%)
        leadershipCountAgent: randomMetric(0, 50),        // Leadership Count (15%)
        latencyAgent: randomMetric(10, 150),              // Latency (25%)
        memoryAvailableAgent: randomMetric(40, 100),      // Available Memory (10%)
        responsivenessAgent: randomMetric(60, 100),       // Responsiveness (10%)
        cpuLoadAgent: randomMetric(5, 60),                // CPU Load (5%)
        storageAvailableAgent: randomMetric(50, 100),     // Storage Availability (5%)
        healthProjectedAgent: randomMetric(50, 100)       // Projected Health Score (20%)
    });
});

context.set("tableBuffer", tableData);


// Final output
msg.payload = {
    agentLogs_flat: tableData
};

return msg;

