const grouped = {};

logs.forEach(log => {
    if (!grouped[log.node]) grouped[log.node] = [];
    grouped[log.node].push(log);
});

const outputs = Object.entries(grouped).map(([node, entries]) => {
    return { payload: entries, topic: node };
});

return [outputs];

