// Accepts either an array of rows in payload.agentLogs_flat OR a single row
function pushRow(row){
  const node = row.node || 'unknown';
  const tmin = Math.floor((new Date(row.timestamp||Date.now())).getTime()/60000);
  if (row.level === 'ERROR') {
    buckets[node] = buckets[node] || {};
    buckets[node][tmin] = (buckets[node][tmin]||0) + 1;
  }
}

let buckets = flow.get('errBuckets') || {};
const p = msg.payload || {};
if (Array.isArray(p.agentLogs_flat)) {
  for (const r of p.agentLogs_flat) pushRow(r);
} else if (Array.isArray(p)) {
  for (const r of p) pushRow(r);
} else if (p && typeof p === 'object') {
  pushRow(p);
}
flow.set('errBuckets', buckets);

// Build series for each node for last 60 minutes
const nowMin = Math.floor(Date.now()/60000);
const outMsgs = [];
for (const node of Object.keys(buckets)){
  const data = [];
  for (let t = nowMin-59; t<=nowMin; t++) data.push({x: t*60000, y: (buckets[node][t]||0)});
  outMsgs.push({
    topic: node,
    payload: [{ series:["Errors/min"], data:[data], labels:[""] }]
  });
}
return [outMsgs];

