// Input:  msg.payload.agentLogs_flat = [{ node, role, api?, message?, timestamp?, source? }, ...]
// Output: msg.payload.topology = { agents:[{id,label,role,api,status}], apis:[{id,label,url}], edges:[{from,to,type}] }
// Notes:
//  - Marks agent online if seen in last 90s, else offline (kept so the graph stays stable)
//  - Adds a yellow API box per agent + an 'API' edge
//  - Infers Coordination edges: coordinator -> follower
//  - Parses simple keywords in messages for Election / Replication / Query edges

const flat = (msg.payload && msg.payload.agentLogs_flat) || [];
const cache = context.get('agentCache') || {}; // { id: {role, api, lastSeen} }
const now = Date.now();
const ONLINE_WINDOW = 90 * 1000;  // 90s

// helpers
const seen = new Set();
const agents = {};
const apis = {};   // by apiId (agentId+"-api")
const edges = [];

function guessApiFromNode(id){
  // e.g. node-18003 -> http://localhost:18003
  const m = String(id).match(/(\d{2,5})$/);
  if (!m) return undefined;
  return `http://localhost:${m[1]}`;
}

// 1) Collect agents from logs & cache
for (const row of flat) {
  const id = row.node || 'unknown';
  if (!id) continue;
  const role = row.role || cache[id]?.role || 'Unknown';
  const api = row.api || cache[id]?.api || row.source?.startsWith('http') ? row.source : undefined;

  cache[id] = { role, api: api || cache[id]?.api, lastSeen: now };
  agents[id] = {
    id,
    label: id,
    role,
    api: cache[id].api || api || guessApiFromNode(id),
    status: 'online'
  };
  seen.add(id);
}

// keep recently seen agents from cache (up to 10 minutes)
for (const id of Object.keys(cache)) {
  if (seen.has(id)) continue;
  const age = now - (cache[id].lastSeen || 0);
  if (age < 10 * 60 * 1000) {
    agents[id] = {
      id,
      label: id,
      role: cache[id].role || 'Unknown',
      api: cache[id].api || guessApiFromNode(id),
      status: age <= ONLINE_WINDOW ? 'online' : 'offline'
    };
  }
}

// 2) API nodes + edges
for (const id of Object.keys(agents)) {
  const a = agents[id];
  const apiLabel = 'API';
  const apiUrl = a.api;
  const apiId = `${id}-api`;
  apis[apiId] = { id: apiId, label: apiLabel, url: apiUrl };
  edges.push({ from: id, to: apiId, type: 'API' });
}

// 3) Baseline Coordination edges: Coordinator -> everyone else
const ids = Object.keys(agents);
const coordinators = ids.filter(i => /coordinator/i.test(agents[i].role || ''));
const followers = ids.filter(i => !/coordinator/i.test(agents[i].role || ''));
for (const c of coordinators) {
  for (const f of followers) { if (c !== f) edges.push({ from: c, to: f, type: 'Coordination' }); }
}

// 4) Parse logs to add Election / Replication / Query edges
function edgeKey(e){ return `${e.from}->${e.to}#${e.type}`; }
const dedup = new Set(edges.map(edgeKey));

for (const row of flat) {
  const src = String(row.node || '');
  const m = String(row.message || '').toLowerCase();
  let mm;
  // Election
  mm = m.match(/vote\s+for\s+([\w-:.]+)/); if (mm) { const to=mm[1]; const e={from:src,to,type:'Election'}; if(!dedup.has(edgeKey(e))){edges.push(e); dedup.add(edgeKey(e));}}
  mm = m.match(/leader\s*=\s*([\w-:.]+)/); if (mm) { const to=mm[1]; const e={from:src,to,type:'Election'}; if(!dedup.has(edgeKey(e))){edges.push(e); dedup.add(edgeKey(e));}}
  // Replication
  mm = m.match(/replicat\w*\s+(to|→)\s+([\w-:.]+)/); if (mm) { const to=mm[2]; const e={from:src,to,type:'Replication'}; if(!dedup.has(edgeKey(e))){edges.push(e); dedup.add(edgeKey(e));}}
  mm = m.match(/replicat\w*\s+from\s+([\w-:.]+)/); if (mm) { const from=mm[1]; const e={from,to:src,type:'Replication'}; if(!dedup.has(edgeKey(e))){edges.push(e); dedup.add(edgeKey(e));}}
  // Query
  mm = m.match(/query\s+(to|→)\s+([\w-:.]+)/); if (mm) { const to=mm[2]; const e={from:src,to,type:'Query'}; if(!dedup.has(edgeKey(e))){edges.push(e); dedup.add(edgeKey(e));}}
  mm = m.match(/query\s+from\s+([\w-:.]+)/); if (mm) { const from=mm[1]; const e={from,to:src,type:'Query'}; if(!dedup.has(edgeKey(e))){edges.push(e); dedup.add(edgeKey(e));}}
}

// 5) finalize & status
for (const id of Object.keys(agents)) {
  const age = now - (cache[id]?.lastSeen || 0);
  agents[id].status = age <= ONLINE_WINDOW ? 'online' : 'offline';
}

// 3b) Mesh edges: connect every pair of agents (undirected -> render as two directed for clarity)
for (let i = 0; i < ids.length; i++) {
  for (let j = i + 1; j < ids.length; j++) {
    const a = ids[i], b = ids[j];
    edges.push({ from: a, to: b, type: 'Mesh' });
    edges.push({ from: b, to: a, type: 'Mesh' });
  }
}

context.set('agentCache', cache);
msg.payload = msg.payload || {};
msg.payload.topology = {
  agents: Object.values(agents),
  apis: Object.values(apis),
  edges
};
return msg;

// Guarantees node-18001..node-18008 appear on each tick, even with no logs
// Input:  msg.payload.agentLogs_flat (array)
// Output: msg.payload.agentLogs_flat (augmented)
const flat = Array.isArray(msg.payload?.agentLogs_flat) ? msg.payload.agentLogs_flat : [];
const have = new Set(flat.map(r => r.node));
const ports = [18001,18002,18003,18004,18005,18006,18007,18008];
const now = new Date().toISOString();

const fillers = ports
  .map(p => `node-${p}`)
  .filter(id => !have.has(id))
  .map(id => ({
    line: -1,
    timestamp: now,
    level: 'INFO',
    message: '(no logs yet)',
    source: '',
    node: id,
    cpu: 0,
    mem: 0,
    latency: 0,
    health: 0,
    replication: 0,
    io: 0,
    queryRate: 0,
    role: 'Unknown'
  }));

msg.payload = msg.payload || {};
msg.payload.agentLogs_flat = flat.concat(fillers);
return msg;

// From agentLogs_flat, keep the latest row per node (for cards)
const rows = Array.isArray(msg.payload?.agentLogs_flat) ? msg.payload.agentLogs_flat : [];
const latest = {};
for (const r of rows) { latest[r.node] = r; }
msg.payload = { cards: Object.values(latest) };
